mapper.select:
select id, username, role, user_account, phone, status, avatar, bio, create_time from user
username like concat('%',#{username},'%') role = #{role} create_time BETWEEN #{startTime} AND #{endTime} AND (is_deleted IS NULL OR is_deleted = '0')
order by create_time desc limit #{start},#{size}

mapper.update:
UPDATE user
SET total_like_count = GREATEST(COALESCE(total_like_count, 0) + #{delta},0), update_time = NOW()
WHERE id = #{id}

UPDATE user
SET follow_count = GREATEST(COALESCE(follow_count, 0) + #{delta},0), update_time = NOW()
WHERE id = #{id}

UPDATE user
SET fan_count = GREATEST(COALESCE(fan_count, 0) + #{delta},0), update_time = NOW()
WHERE id = #{id}

UPDATE user
username = #{userInfo.username}, avatar = #{userInfo.avatar}, cover = #{userInfo.cover}, bio = #{userInfo.bio}, birthday = #{userInfo.birthday}, location = #{userInfo.location}, update_time = NOW()
WHERE id = #{userId}
